-- CET-4 高频词补充包（在 scripts/seed_words.sql 之后执行）
-- 用途：将 CET-4 词库从 42 词扩充至约 150 词，覆盖真题高频动词/名词/形容词
-- 执行：docker exec -i enstud-mysql mysql -uroot -proot --default-character-set=utf8mb4 enstud_app < scripts/seed_words_cet4_extra.sql


-- 更新 CET-4 词库词数
UPDATE enstud_wordbook SET word_count = (SELECT COUNT(*) FROM enstud_word WHERE wordbook_id = 1) WHERE id = 1;

-- 清理旧版 Mock 占位翻译（让文章翻译走 DeepSeek 真实翻译并重新缓存）
UPDATE enstud_article SET title_cn = NULL, summary_cn = NULL, content_cn = NULL
WHERE title_cn LIKE '%的中文翻译）' OR summary_cn LIKE '%的中文翻译）' OR content_cn LIKE '%的中文翻译）';
